duction work\n        run: |\n          node --input-type=module <<'JS'\n          import assert from 'node:assert/strict';\n          const r=await fetch('https://api.github.com/repos/shiftsometimber/shift-core/actions/runs/36341844316',{headers:{Authorization:'Bearer '+process.env.GITHUB_TOKEN}});\n          assert(r.ok);const run=await r.json();assert.equal(run.conclusion,'success');assert.equal(run.head_sha,'90b1e29db85591b84dec642c3304641bc9545529');\n          JS\n      - name: Require verified homepage speed candidate and current CSS bytes\n        run: |\n          node --input-type=module <<'JS'\n          import assert from 'node:assert/strict';\n          import {createHash} from 'node:crypto';\n          import {RETA_STYLES} from './reta-styles-data.mjs';\n          import {HOME_BLOCKING_STYLES} from './home-blocking-styles.mjs';\n          import {styles as pwaStyles} from './my-timber-pwa/presentation.mjs';\n          const r=await fetch('https://api.github.com/repos/shiftsometimber/shift-core/actions/runs/36469397727',{headers:{Authorization:'Bearer '+process.env.GITHUB_TOKEN}});assert(r.ok);const run=await r.json();assert.equal(run.conclusion,'success');assert.equal(run.head_sha,'44c895d732cf801c4cff90564244fa5ee8997523');\n          const sha=x=>createHash('sha256').update(x).digest('hex');\n          for(const [path,css] of Object.entries({...RETA_STYLES,...HOME_BLOCKING_STYLES,'/assets/my-timber-pwa.css':pwaStyles})){const r=await fetch('https://shiftsometimber.co.uk'+path);assert(r.ok);assert.equal(sha(await r.text()),sha(css),'CSS changed since preview: '+path)}\n          JS\n      - name: Install exact Wrangler toolchain\n        run: npm install --no-audit --no-fund\n      - name: Recover only the evidenced cancelled runtime to the last verified release\n        run: node shift-coach/recover-cancelled-release.mjs\n      - name: Prepare and launch verification browsers before deployment\n        timeout-minutes: 3\n        run: |\n          np